 $fine=new Library\Services\FineService($db);$preview=$fine->previewBalance($readerIds[0]);$assert($preview===21900.0,'Read-only preview includes unassessed overdue');$assert(!$db->query('SELECT id FROM fine_charges WHERE reader_id='.$readerIds[0])->fetch(),'Preview does not create financial charges');$assert($fine->balance($readerIds[0])===$preview,'Canonical assessed balance equals preview');
 $repo=new Library\Repositories\FineRepository($db);$q=$db->query('SELECT * FROM fine_charges WHERE reader_id='.$readerIds[0]);$charge=$q->fetch();$db->prepare('INSERT INTO fine_waivers(fine_charge_id,amount,reason,waived_by) VALUES(?,?,?,?)')->execute([$charge['id'],'900','QA waiver',$accounts[0]['id']]);$assert($fine->previewBalance($readerIds[0])===21000.0,'Waiver deducted using ledger');$assert($fine->balance($readerIds[0])===$fine->previewBalance($readerIds[0]),'Canonical balance agrees after waiver');
